import type { NextRequest } from 'next/server'
import type { LocalPost } from '@/types'

const posts: Map<number, LocalPost> = new Map([
  [
    1,
    {
      id: 1,
      title: 'First Post',
      content: 'This is the first post',
      createdAt: new Date().toISOString(),
    },
  ],
  [
    2,
    {
      id: 2,
      title: 'Second Post',
      content: 'This is the second post',
      createdAt: new Date().toISOString(),
    },
  ],
])

export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  const post = posts.get(Number(id))

  if (!post) {
    return Response.json({ error: 'Post not found' }, { status: 404 })
  }

  return Response.json(post)
}

export async function PUT(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  const body = (await request.json()) as { title?: string; content?: string }

  const existingPost = posts.get(Number(id))

  if (!existingPost) {
    return Response.json({ error: 'Post not found' }, { status: 404 })
  }

  const updatedPost: LocalPost = {
    ...existingPost,
    title: body.title ?? existingPost.title,
    content: body.content ?? existingPost.content,
  }

  posts.set(Number(id), updatedPost)

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params
  const deleted = posts.delete(Number(id))

  if (!deleted) {
    return Response.json({ error: 'Post not found' }, { status: 404 })
  }

  return Response.json({ message: `Post ${id} deleted successfully` })
}

